pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testRegression_property() public {
        c.SetMinSum(0);
        address dummyLog = address(0xdead);
        c.SetLogFile(dummyLog);
        c.Collect(0);
        bool ok;
        try c.Initialized() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
